    const newNodes = pendingTasks.map((task, i) => ({
      id: task.task_id,
      type: 'task',
      position: { 
        x: 250, 
        y: 100 + (approvedTasks.length + i) * 150 
      },
      data: { task },
    }));

    // Create edges between all consecutive tasks
