import React, { type ReactElement, type ReactNode } from "react";
import {
  Button as MuiButton,
  type ButtonProps as MuiButtonProps,
  useTheme,
  alpha,
} from "@mui/material";

interface ButtonProps extends MuiButtonProps {
  children: ReactNode;
  colorVariant?: Color;
}

type Color = "transparent" | "green" | "dark-green";

const Button = ({
  children,
  variant = "outlined",
  onClick,
  sx,
  disabled = false,
  colorVariant = "transparent",
  ...props
}: ButtonProps): ReactElement => {
  const theme = useTheme();

  let color = "transparent";
  let borderColor = theme.palette.primary.main;
  let textColor = theme.palette.primary.main;

  if (colorVariant === "green") {
    color = theme.palette.primary.main;
    textColor = "#ffffff";
  }
  if (colorVariant === "dark-green") {
    color = theme.palette.primary.dark;
    textColor = "#ffffff";
  }

  let hoverColor = alpha(theme.palette.primary.main, 0.04);
  let hoverBorderColor = theme.palette.primary.dark;

  if (colorVariant === "green") {
    hoverColor = theme.palette.primary.dark;
  }
  if (colorVariant === "dark-green") {
    hoverColor = alpha(theme.palette.primary.dark, 0.8);
  }

  return (
    <MuiButton
      variant={variant}
      onClick={onClick}
      disabled={disabled}
      sx={{
        backgroundColor: color,
        borderColor: borderColor,
        color: textColor,
        borderRadius: 1,
        boxShadow: "none",
        textTransform: "none",
        "&:hover": {
          backgroundColor: hoverColor,
          borderColor: hoverBorderColor,
        },
        "&:disabled": {
          opacity: 0.5,
          cursor: "not-allowed",
        },
        ...sx,
      }}
      {...props}
    >
      {children}
    </MuiButton>
  );
};

export { Button };

