            return jsonify({'success': False, 'error': str(e)}), 500

    @app.route('/api/assistant-chats', methods=['GET'])
    def get_assistant_chats():
        try:
            print("GET /api/assistant-chats - Started")
            metadata = load_metadata()
            chats = [c.model_dump() for c in metadata.chats]
            print(f"GET /api/assistant-chats - Success ({len(chats)} chats)")
            return jsonify({'success': True, 'chats': chats})
        except Exception as e:
            print(f"GET /api/assistant-chats - Failed: {str(e)}")
            traceback.print_exc()
            return jsonify({'success': False, 'error': str(e)}), 500

    @app.route('/api/plan/<chatId>', methods=['GET'])
