      target: edge.to,
      type: 'smoothstep',
    }));

    setNodes(flowNodes);
    setEdges(flowEdges);
  }, [plan, setNodes, setEdges]);

  if (loading) {
    return <Box sx={{ p: 2 }}><Typography>Loading plan...</Typography></Box>;
  }

  if (!plan) {
    return <Box sx={{ p: 2 }}><Typography>No plan for this chat yet</Typography></Box>;
  }

  return (
      <Paper sx={{ height: '100%', position: 'relative', overflow: 'hidden', m: 0, borderRadius: 0 }}>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          nodeTypes={nodeTypes}
          panOnDrag={true}
          zoomOnScroll={true}
          panOnScroll={false}
          minZoom={0.1}
          maxZoom={2}
          defaultViewport={{ x: 0, y: 0, zoom: 1 }}
          style={{ position: 'absolute', inset: 0 }}
        >
          <Controls />
          <Background />
        </ReactFlow>
      </Paper>
  );
}

