import { Handle, Position } from 'reactflow';
import { Paper, Typography } from '@mui/material';

interface FlowNodeData {
  label: string;
  isAnalyzing?: boolean;
  selected?: boolean;
  status?: 'pending' | 'in_progress' | 'completed' | 'blocked';
}

export function FlowNode({ data, selected }: { data: FlowNodeData; selected?: boolean }) {
  const { label, isAnalyzing, status } = data;
  const isSelected = selected || data.selected;

  // Status-based styling
  const getStatusStyle = () => {
    if (isSelected) {
      return {
        backgroundColor: 'rgba(135, 174, 115, 0.2)',
        border: '2px solid',
        borderColor: 'primary.main',
      };
    }

    if (isAnalyzing) {
      return {
        backgroundColor: 'warning.light',
        border: '2px solid',
        borderColor: 'warning.main',
      };
    }

    switch (status) {
      case 'completed':
        return {
          background: 'repeating-linear-gradient(45deg, #e0e0e0, #e0e0e0 10px, #f0f0f0 10px, #f0f0f0 20px)',
          border: '1px solid',
          borderColor: '#bdbdbd',
          opacity: 0.7,
        };
      case 'in_progress':
        return {
          backgroundColor: 'rgba(255, 193, 7, 0.1)',
          border: '2px solid',
          borderColor: 'warning.main',
        };
      case 'blocked':
        return {
          backgroundColor: 'rgba(244, 67, 54, 0.1)',
          border: '2px solid',
          borderColor: 'error.main',
        };
      default:
        return {
          backgroundColor: 'background.paper',
          border: '1px solid',
          borderColor: 'divider',
        };
    }
  };

  return (
    <Paper 
      elevation={0}
      sx={{ 
        p: 2, 
        minWidth: 120,
        maxWidth: 200,
        textAlign: 'center',
        cursor: 'pointer',
        ...getStatusStyle(),
        transition: 'all 0.3s ease',
        animation: isAnalyzing ? 'pulse 1.5s ease-in-out infinite' : 'none',
        '@keyframes pulse': {
          '0%, 100%': {
            transform: 'scale(1)',
          },
          '50%': {
            transform: 'scale(1.05)',
          },
        },
      }}
    >
      <Handle type="target" position={Position.Top} />

      <Typography 
        variant="body2" 
        fontWeight={600}
        sx={{ 
          textTransform: 'capitalize',
        }}
      >
        {label}
      </Typography>

      <Handle type="source" position={Position.Bottom} />
    </Paper>
  );
}

