              size="small"
              color={taskType === 'good' ? 'success' : 'error'}
            />
          )}
        </Box>

        {/* Brief Description */}
        <Box sx={{ mb: 2 }}>
          <Typography 
            variant="caption" 
            color="text.secondary"
            sx={{ mb: 0.5, display: 'block', fontWeight: 600 }}
