        }}
      >
        {/* Task Type & Quality Badge */}
        <Box sx={{ mb: 2, display: 'flex', gap: 1, alignItems: 'center', flexWrap: 'wrap' }}>
          <Chip 
            label={task.title || task.suggested_type || task.type || 'uncategorized'}
            size="small"
            color="primary"
          />
          {isLearnerTask && (
            <Chip 
              icon={task.type === 'good' ? <CheckCircle /> : <Error />}
              label={task.type === 'good' ? 'Good Trajectory' : 'Bad Trajectory'}
              size="small"
              color={task.type === 'good' ? 'success' : 'error'}
            />
          )}
          {isPlanNode && task.status && (
            <Chip label={task.status} size="small" />
          )}
        </Box>

        {/* Brief Description */}
        <Box sx={{ mb: 2 }}>
          <Typography 
            variant="caption" 
            color="text.secondary"
            sx={{ mb: 0.5, display: 'block', fontWeight: 600 }}
          >
            Description
          </Typography>
          <Typography 
            variant="body2"
            sx={{ whiteSpace: 'pre-wrap' }}
          >
            {task.description || task.task}
          </Typography>
        </Box>

        <Divider sx={{ my: 2 }} />

        {/* Messages - Show either messages array or raw_data */}
        {((task.messages && task.messages.length > 0) || task.raw_data) && (
          <>
            <CollapsibleSection
              title={
                <Typography variant="caption" color="text.secondary" fontWeight={600}>
                  💭 {task.messages ? `Messages (${task.messages.length})` : 'Raw Chat Data'}
                </Typography>
              }
              defaultOpen={false}
              sx={{ mb: 2, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}
            >
              <Box 
                sx={{ 
                  maxHeight: 300,
                  overflow: 'auto',
                  fontFamily: 'monospace',
                  fontSize: '0.7rem',
                  bgcolor: 'action.hover',
                  p: 1,
                  borderRadius: 1,
                  whiteSpace: 'pre-wrap',
                }}
              >
                {task.messages && task.messages.length > 0 ? (
                  task.messages.map((msg: string, idx: number) => (
                    <Typography 
                      key={idx}
                      variant="caption"
                      sx={{ 
                        display: 'block',
                        mb: 0.5,
                        fontFamily: 'monospace',
                      }}
                    >
                      • {msg}
                    </Typography>
                  ))
                ) : (
                  <Typography 
                    variant="caption"
                    sx={{ 
                      fontFamily: 'monospace',
                      whiteSpace: 'pre-wrap',
                    }}
                  >
                    {task.raw_data}
                  </Typography>
                )}
              </Box>
            </CollapsibleSection>
            <Divider sx={{ my: 2 }} />
          </>
        )}

        {/* Analyzed Fields */}
        {isLearnerTask && (
          <>
            {/* Reasoning */}
            {task.reasoning && (
              <Box sx={{ mb: 2 }}>
                <Typography 
                  variant="caption" 
                  color="text.secondary"
                  sx={{ mb: 0.5, display: 'block', fontWeight: 600 }}
                >
                  💡 Reasoning
                </Typography>
                <Typography 
                  variant="body2"
                  sx={{ whiteSpace: 'pre-wrap', fontSize: '0.8rem' }}
                >
                  {task.reasoning}
                </Typography>
              </Box>
            )}

            <Divider sx={{ my: 2 }} />

            {/* Bad Trajectory Fields */}
            {task.type === 'bad' && (
              <>
                {task.problem && (
                  <Box sx={{ mb: 2, p: 1.5, bgcolor: 'action.hover', borderRadius: 1 }}>
                    <Typography 
                      variant="caption" 
                      sx={{ mb: 0.5, display: 'block', fontWeight: 600 }}
                    >
                      ⚠️ Problem
                    </Typography>
                    <Typography 
                      variant="body2"
                      sx={{ whiteSpace: 'pre-wrap', fontSize: '0.8rem' }}
                    >
                      {task.problem}
                    </Typography>
                  </Box>
                )}

                {task.failure_point && (
                  <Box sx={{ mb: 2, p: 1.5, bgcolor: 'action.hover', borderRadius: 1 }}>
                    <Typography 
                      variant="caption" 
                      sx={{ mb: 0.5, display: 'block', fontWeight: 600 }}
                    >
                      📍 Failure Point
                    </Typography>
                    <Typography 
                      variant="body2"
                      sx={{ whiteSpace: 'pre-wrap', fontSize: '0.8rem' }}
                    >
                      {task.failure_point}
                    </Typography>
                  </Box>
                )}

                {task.guardrail && (
                  <Box sx={{ mb: 2, p: 1.5, bgcolor: 'action.hover', borderRadius: 1 }}>
                    <Typography 
                      variant="caption" 
                      sx={{ mb: 0.5, display: 'block', fontWeight: 600 }}
                    >
                      🛡️ Guardrail
                    </Typography>
                    <Typography 
                      variant="body2"
                      sx={{ whiteSpace: 'pre-wrap', fontSize: '0.8rem' }}
                    >
                      {task.guardrail}
                    </Typography>
                  </Box>
                )}

                <Divider sx={{ my: 2 }} />
              </>
            )}

            {/* Rules - Learner Task Rules */}
            {rules.length > 0 && (
              <Box sx={{ mb: 2 }}>
                <Typography 
                  variant="caption" 
                  color="text.secondary"
                  sx={{ mb: 1, display: 'block', fontWeight: 600 }}
                >
                  📋 Extracted Rules ({rules.length})
                </Typography>
                {rules.map((rule: any, idx: number) => (
                  <CollapsibleSection
                    key={idx}
                    title={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flex: 1 }}>
                        <Typography variant="body2" fontWeight={600}>
                          Rule {idx + 1}
                        </Typography>
                        {rule.confidence && (
                          <Chip 
                            label={`${rule.confidence}/10`} 
                            size="small" 
                            sx={{ ml: 'auto' }}
                          />
                        )}
                      </Box>
                    }
                    defaultOpen={false}
                    sx={{ mb: 1, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}
                  >
                    <Box>
                      <Typography 
                        variant="body2" 
                        sx={{ mb: 1, fontWeight: 600 }}
                      >
                        {rule.rule}
                      </Typography>
                      <Typography 
                        variant="caption" 
                        color="text.secondary"
                        sx={{ display: 'block', whiteSpace: 'pre-wrap' }}
                      >
                        {rule.reasoning}
                      </Typography>
                      {rule.confidence && rule.decay && (
                        <Box sx={{ mt: 1, display: 'flex', gap: 1 }}>
                          <Chip label={`Confidence: ${rule.confidence}/10`} size="small" />
                          <Chip label={`Decay: ${rule.decay}/10`} size="small" />
                        </Box>
                      )}
                    </Box>
                  </CollapsibleSection>
                ))}
              </Box>
            )}
          </>
        )}

        {/* Rules - Plan Node Rules (Assistant) */}
        {isPlanNode && rules.length > 0 && (
          <Box sx={{ mb: 2 }}>
            <Typography 
              variant="caption" 
              color="text.secondary"
              sx={{ mb: 1, display: 'block', fontWeight: 600 }}
            >
              📋 Rules to Follow ({rules.length})
            </Typography>
            {rules.map((rule: any, idx: number) => (
              <CollapsibleSection
                key={idx}
                title={
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flex: 1 }}>
                    <Typography variant="body2" fontWeight={600}>
                      {rule.name || `Rule ${idx + 1}`}
                    </Typography>
                  </Box>
                }
                defaultOpen={false}
                sx={{ mb: 1, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}
              >
                <Box>
                  <Typography 
                    variant="body2" 
                    sx={{ mb: 1, fontWeight: 600 }}
                  >
                    {rule.description}
                  </Typography>
                  <Typography 
                    variant="caption" 
                    color="text.secondary"
                    sx={{ display: 'block', whiteSpace: 'pre-wrap' }}
                  >
                    {rule.source}
                  </Typography>
                </Box>
              </CollapsibleSection>
            ))}
          </Box>
        )}

        {/* Audit Trail (for PlanNode) */}
        {task.audit && task.audit.length > 0 && (
          <>
            <Divider sx={{ my: 2 }} />
            <Box sx={{ mb: 2 }}>
              <Typography 
                variant="caption" 
                color="text.secondary"
                sx={{ mb: 1, display: 'block', fontWeight: 600 }}
              >
                📝 Audit Trail ({task.audit.length})
              </Typography>
              {task.audit.map((entry: any, idx: number) => (
                <Box 
                  key={idx}
                  sx={{ 
                    mb: 1, 
                    p: 1, 
                    bgcolor: 'action.hover', 
                    borderRadius: 1,
                    fontSize: '0.75rem',
                  }}
                >
                  <Typography variant="caption" sx={{ display: 'block', fontWeight: 600 }}>
                    {new Date(entry.at).toLocaleString()} - {entry.who}
                  </Typography>
                  <Typography variant="caption" sx={{ display: 'block' }}>
                    {entry.action}
                  </Typography>
                  {entry.details && (
                    <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                      {entry.details}
                    </Typography>
                  )}
                </Box>
              ))}
            </Box>
          </>
        )}

        {/* Task/Node ID */}
        <Box sx={{ mt: 3, pt: 2, borderTop: '1px solid', borderColor: 'divider' }}>
          <Typography 
            variant="caption" 
            color="text.secondary"
            sx={{ display: 'block', fontFamily: 'monospace' }}
          >
            ID: {task.task_id || task.id}
          </Typography>
        </Box>
      </Box>
    </Paper>
  );
}

